# Auto-generated by scripts/blossom_hd_frames.py (its own regen mode) from
# the Fufu-Blossom Codex pet pack (~/.codex/pets/fufu-blossom/spritesheet.webp,
# row 0 idle, 6 frames) — do not edit by hand. Same extraction as
# qinglong_hd_frames, forensically pinned to it: per-frame
# quantize(256, FASTOCTREE) on the 1:1 snapped-bbox crop reproduces the
# shipped qinglong PNGs with 0 differing pixels (the "NEAREST-fitted at 3/4"
# line in the qinglong header is legacy mosaic-port flavor text — CONTEXT.md's
# 1:1 account is the real one). Idle-row union alpha bbox snapped outward to
# the 4px art grid, cropped 1:1, centered on the 144x160 slot the qinglong
# sprite filled: blossom's snapped bbox is 136x144 (the character is drawn
# smaller in its cell), left as-is — non-integer NEAREST upscaling would
# break the 4px art blocks. IDLE_MS is the pack's previews/animation-spec.json
# row 0 (identical values to the qinglong pack — same series). Regenerate:
# python3 scripts/blossom_hd_frames.py
import base64  # stdlib only at import time: CI's wall.yml runs gen_acfufu_card without Pillow
import re
from pathlib import Path

BOX = (144, 160)

IDLE_MS = [280, 110, 110, 140, 140, 320]  # pack previews/animation-spec.json, row 0

# --- frames: auto block (regen rewrites the list below) ---
PNGS = [
    "",
    "",
    "",
    "",
    "",
    "",
]
# --- end frames ---

_SPRITE_SLOT = BOX  # the 144x160 card slot


def _regen(pack=None):
    """Re-extract the 6 idle frames from the installed pack and splice them
    into the auto block in place."""
    import io

    from PIL import Image

    pack = Path(pack or Path.home() / ".codex/pets/fufu-blossom/spritesheet.webp")
    sheet = Image.open(pack).convert("RGBA")
    cw, ch = sheet.size[0] // 8, sheet.size[1] // 9  # codex v1 atlas: 8x9 cells
    cells = [sheet.crop((c * cw, 0, (c + 1) * cw, ch)) for c in range(6)]
    boxes = [cell.getchannel("A").getbbox() for cell in cells]
    # union bbox, snapped outward to the 4px art grid
    u = (min(b[0] for b in boxes), min(b[1] for b in boxes),
         max(b[2] for b in boxes), max(b[3] for b in boxes))
    box4 = (u[0] - u[0] % 4, u[1] - u[1] % 4,
            u[2] + -u[2] % 4, u[3] + -u[3] % 4)
    w, h = box4[2] - box4[0], box4[3] - box4[1]
    if w > _SPRITE_SLOT[0] or h > _SPRITE_SLOT[1]:
        raise SystemExit(f"snapped bbox {w}x{h} overflows the {_SPRITE_SLOT} slot")
    ox, oy = (_SPRITE_SLOT[0] - w) // 2, (_SPRITE_SLOT[1] - h) // 2
    out = []
    for cell in cells:
        frame = cell.crop(box4).copy()
        canvas = Image.new("RGBA", _SPRITE_SLOT, (0, 0, 0, 0))
        canvas.paste(frame, (ox, oy))
        buf = io.BytesIO()
        canvas.quantize(256, method=Image.FASTOCTREE).save(buf, "PNG")
        out.append(base64.b64encode(buf.getvalue()).decode())
    p = Path(__file__).resolve()
    text = p.read_text()
    # marker-lookahead splice: base64 has no ']' so .*? stops at the closer
    # either way; the lookahead pins it to the auto block's terminator
    filled = "PNGS = [\n" + "".join(f'    "{b}",\n' for b in out) + "]"
    text, n = re.subn(r"PNGS = \[.*?\n\](?=\n# --- end frames ---)",
                      lambda _: filled, text, count=1, flags=re.S)
    if n != 1:
        raise SystemExit("regen: auto block not found — markers missing?")
    p.write_text(text)
    print(f"regen: {len(out)} frames, bbox {w}x{h} at offset ({ox},{oy}), pack {pack}")


if __name__ == "__main__":
    _regen()
